import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"Source Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"source-inventory.md","filePath":"source-inventory.md","lastUpdated":1781808154000}'),r={name:"source-inventory.md"};function c(n,e,s,d,l,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="source-inventory" tabindex="-1">Source Inventory <a class="header-anchor" href="#source-inventory" aria-label="Permalink to &quot;Source Inventory&quot;">​</a></h1><p>This document defines exactly what is fetched from our data source, what fields are consumed, and where records flow.</p><hr><h2 id="geofabrik-osm-extracts-pbf" tabindex="-1">Geofabrik OSM Extracts (PBF) <a class="header-anchor" href="#geofabrik-osm-extracts-pbf" aria-label="Permalink to &quot;Geofabrik OSM Extracts (PBF)&quot;">​</a></h2><ul><li><strong>Source name</strong>: Geofabrik country extracts</li><li><strong>Purpose</strong>: Unified places, airports, accommodations, and discovery POI backbone for autosuggest destinations</li><li><strong>Fetch method</strong>: <code>scripts/fetch_osm.sh</code> via <code>curl</code> from <code>https://download.geofabrik.de/{geofabrik_path}-latest.osm.pbf</code></li><li><strong>Fetch controls</strong>: lock file + ETag check + manifest write. If local ETag matches and output files exist, download and osmium tags-filtering are skipped entirely.</li><li><strong>Schedule</strong>: Weekly recommended</li><li><strong>Artifact format</strong>: <code>.osm.pbf</code>, then filtered <code>.osm.pbf</code>, then <code>.geojsonseq</code></li><li><strong>Fields consumed</strong>: <ul><li><code>name</code>, <code>name:*</code> (all translations)</li><li><code>alt_name</code>, <code>loc_name</code>, <code>official_name</code>, <code>short_name</code>, <code>old_name</code>, <code>int_name</code></li><li><code>admin_level</code>, <code>boundary</code>, <code>place</code></li><li><code>railway</code>, <code>tourism</code>, <code>leisure</code>, <code>amenity</code>, <code>historic</code>, <code>natural</code>, <code>shop</code></li><li><code>population</code>, <code>wikidata</code>, <code>wikipedia</code></li><li><code>iata</code>, <code>icao</code> (airports)</li><li><code>stars</code> (hotels)</li><li><code>cuisine</code> (restaurants)</li><li>geometry and bbox</li></ul></li><li><strong>Entities produced</strong>: 19 classes (Airport, Hotel, City, Region, Neighborhood, TrainStation, TouristAttraction, Restaurant, etc.)</li><li><strong>Stable ID strategy</strong>: <code>osm-{type}-{id}</code> from exported feature id</li><li><strong>Refresh model</strong>: Incremental per-country build with full index swap.</li><li><strong>Downstream index target</strong>: <code>places</code> index in Meilisearch</li><li><strong>Known risks</strong>: <ul><li>admin-level semantics vary by country.</li><li>multilingual name coverage is uneven in low-profile regions.</li></ul></li></ul><hr><h2 id="wikidata-wikipedia-pageviews-enrichment" tabindex="-1">Wikidata &amp; Wikipedia Pageviews Enrichment <a class="header-anchor" href="#wikidata-wikipedia-pageviews-enrichment" aria-label="Permalink to &quot;Wikidata &amp; Wikipedia Pageviews Enrichment&quot;">​</a></h2><ul><li><strong>Source name</strong>: Wikidata API/SPARQL &amp; Wikimedia pageviews API</li><li><strong>Purpose</strong>: Place enrichment (sitelinks count, labels, monthly Wikipedia pageviews) to derive a <code>popularity_score</code></li><li><strong>Fetch method</strong>: API calls with local cache (<code>data/cache/enrichment.sqlite</code>)</li><li><strong>Schedule</strong>: Cache-first during country build-data runs. If a country&#39;s <code>.geojsonseq</code> checksums haven&#39;t changed, the entire enrichment is skipped for that country.</li><li><strong>Fields consumed</strong>: <ul><li>Sitelinks count (Wikidata)</li><li>Monthly pageviews (Wikimedia REST API)</li></ul></li><li><strong>Downstream index target</strong>: Mapped to <code>popularity_score</code> on <code>Place</code> documents.</li></ul>',8)])])}const h=o(r,[["render",c]]);export{g as __pageData,h as default};
